function simplifyPath(path) {
  const parts = path.split('/');
  let idx = parts.indexOf('..');
  while (idx !== -1) {
    parts.splice(idx, 1);
    for (let j = idx - 1; j >= 0; j--) {
      if (parts[j] !== '' && parts[j] !== '.' && parts[j] !== '..') {
        parts.splice(j, 1);
        break;
      }
    }
    idx = parts.indexOf('..');
  }
  const names = [];
  for (let i = 0; i < parts.length; i++) {
    if (parts[i] !== '' && parts[i] !== '.' && parts[i] !== '..') {
      names.push(parts[i]);
    }
  }
  return '/' + names.join('/');
}

function simplifyPath(path) {
  const stack = [];
  const parts = path.split('/');
  for (let i = 0; i < parts.length; i++) {
    const part = parts[i];
    if (part === '' || part === '.') {
      continue;
    } else if (part === '..') {
      if (stack.length > 0) {
        stack.pop();
      }
    } else {
      stack.push(part);
    }
  }
  return '/' + stack.join('/');
}

